-- Minimal external table contracts; the production calculation function is loaded verbatim.
create table profiles(id uuid primary key, display_name text, email text, employee_code text, joined_at date, left_at date, employment_status text default 'active');
create table staff_payroll_position_versions(staff_id uuid, position_code text, effective_from date);
create table staff_payroll_task_versions(staff_id uuid, task_code text, is_enabled boolean, effective_from date);
create table staff_daily_rate_versions(id uuid default gen_random_uuid(),staff_id uuid,effective_from date,offline_daily_rate_vnd bigint,online_rate_basis_points integer);
create table payroll_policy_versions(id uuid default gen_random_uuid(),policy_code text,parameters jsonb,effective_from date);
create table payroll_source_facts(id uuid default gen_random_uuid(),fact_type text,source_key text,staff_id uuid,student_id uuid,grade integer,amount_vnd bigint,quantity numeric,metadata jsonb default '{}',event_date date,source_code text);
create table time_entries(id uuid,staff_id uuid,work_date date,check_in_mode text,check_in_at timestamptz,check_out_at timestamptz,status text);
create function time_entry_is_verified(uuid) returns boolean language sql as $$select true$$;
create table time_entry_adjustment_requests(time_entry_id uuid,requested_check_in_at timestamptz,requested_check_out_at timestamptz,requested_check_in_mode text,status text,reviewed_at timestamptz);
create table attendance_exception_reviews(time_entry_id uuid,status text);
create table grading_credits(grader_id uuid,credit_units numeric,credited_at timestamptz);
create table student_enrollments(id uuid,student_id uuid,class_id uuid,effective_from date,effective_to date);
create table classes(id uuid,grade integer);
create table students(id uuid,current_grade integer);
create table staff_grade_assignments(id uuid,staff_id uuid,grade integer,effective_from date,effective_to date);
create table finance_cashflow_records(id uuid);
create table sales_commission_accruals(source_cashflow_record_id uuid,crm_case_id uuid);
create table crm_cases(id uuid,lead_source_id uuid);
create table payroll_lead_source_mapping_versions(lead_source_id uuid,payroll_source_code text,effective_from date);
create table coaching_records(id uuid,student_id uuid,assistant_owner_id uuid,opened_at timestamptz);
create table salary_advances(id uuid,staff_id uuid,amount_vnd bigint,request_note text,deduction_period_month date,status text);
create schema auth;
create function auth.uid() returns uuid language sql as $$select '00000000-0000-4000-8000-000000000001'::uuid$$;
create function has_permission(text) returns boolean language sql as $$select true$$;
create function sync_payroll_order_facts(date) returns void language sql as $$select$$;
create function bump_payroll_live_revision(date,text,uuid) returns void language sql as $$select$$;
create table payroll_periods(id uuid primary key default gen_random_uuid(),period_month date,status text,current_calculation_run_id uuid,feedback_opened_at timestamptz,feedback_closed_at timestamptz,feedback_closed_by uuid);
create table payroll_calculation_runs(id uuid primary key default gen_random_uuid(),payroll_period_id uuid,revision integer,status text,reason text,generated_by uuid);
create table payroll_correction_requests(payroll_period_id uuid,status text);
create table payroll_statements(id uuid primary key default gen_random_uuid(),payroll_period_id uuid,calculation_run_id uuid,staff_id uuid,staff_display_name_snapshot text,staff_employee_code_snapshot text,work_units integer,work_hours integer,work_minutes integer);
create table payroll_line_items(id uuid primary key default gen_random_uuid(),payroll_statement_id uuid,line_type text,direction text,amount_vnd bigint,work_minutes integer,quantity numeric,unit_count integer,unit_rate_vnd bigint,unit_label text,policy_code text,source_kind text,source_id text,formula_snapshot jsonb,evidence_snapshot jsonb,note text,created_by uuid,salary_advance_id uuid);
create table payroll_calculation_issues(calculation_run_id uuid,issue_code text,source_fact_id uuid,staff_id uuid,details jsonb);
create table payroll_source_revisions(month date primary key,revision integer,input_fingerprint text,updated_at timestamptz);
alter table salary_advances add deducted_at timestamptz,add deduction_payroll_period_id uuid;
